INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7571404, 1215298, 114285, '<td valign="top">Super stunning shot somewhere in EU most likely, and the winner possibly, all the best!</td>', 'Super stunning shot somewhere in EU most likely, and the winner possibly, all the best!', '2018-06-13 01:06:58.000000', NULL, 1),
(7571405, 1215434, 114285, '<td valign="top">Nice potential, but the processing and saturation is off the beam, tone it down next time :)</td>', 'Nice potential, but the processing and saturation is off the beam, tone it down next time :)', '2018-06-13 01:08:09.000000', NULL, 1),
(7571443, 1215645, 114285, '<td valign="top">Lovely simplicity, not sure it really meets the challenge though, but still a pretty image.</td>', 'Lovely simplicity, not sure it really meets the challenge though, but still a pretty image.', '2018-06-13 05:56:54.000000', NULL, 1),
(7571449, 1215385, 67258, '<td valign="top">What an incredibly effective colour palette!</td>', 'What an incredibly effective colour palette!', '2018-06-13 06:30:46.000000', NULL, 1),
(7571452, 1215434, 67258, '<td valign="top">Very cool light beam, and perfect placement.  Not very keen on your processing style, but then I''m not very keen on my processing either!</td>', 'Very cool light beam, and perfect placement.  Not very keen on your processing style, but then I''m not very keen on my processing either!', '2018-06-13 06:41:05.000000', NULL, 1),
(7571453, 1215452, 67258, '<td valign="top">Yep, but quite a cool photo nonetheless.</td>', 'Yep, but quite a cool photo nonetheless.', '2018-06-13 06:44:01.000000', NULL, 1),
(7571454, 1215606, 67258, '<td valign="top">Beautifully created.</td>', 'Beautifully created.', '2018-06-13 06:44:50.000000', NULL, 1),
(7571485, 1215638, 806, '<td valign="top">Beautiful layers of mountains. Interesting viewpoint with repeating shapes. Prominent shapes are the "magic 3". Just enough detail in the foreground. A bit blown out on the left upper corner.</td>', 'Beautiful layers of mountains. Interesting viewpoint with repeating shapes. Prominent shapes are the "magic 3". Just enough detail in the foreground. A bit blown out on the left upper corner.', '2018-06-13 10:12:58.000000', NULL, 1),
(7571487, 1215602, 806, '<td valign="top">Immediately tells a story. Where is this helicopter going? The distant hills hold the secret! Interesting perspective. I would have liked a little slower shutter speed to show the propellers movement instead of the helicopter just hanging there in the sky.</td>', 'Immediately tells a story. Where is this helicopter going? The distant hills hold the secret! Interesting perspective. I would have liked a little slower shutter speed to show the propellers movement instead of the helicopter just hanging there in the sky.', '2018-06-13 10:16:56.000000', NULL, 1),
(7571489, 1215617, 806, '<td valign="top">Interesting scene. A bit too much sharpening.</td>', 'Interesting scene. A bit too much sharpening.', '2018-06-13 10:20:44.000000', NULL, 1),
(7571490, 1215434, 806, '<td valign="top">The light is too blown out/over saturated.</td>', 'The light is too blown out/over saturated.', '2018-06-13 10:21:34.000000', NULL, 1),
(7571491, 1215629, 806, '<td valign="top">interesting geometry in the mountains. like how the tops of each peak are catching a ribbon of light. Tree adds interesting texture but needs more focus and I think should be farther left in the frame.</td>', 'interesting geometry in the mountains. like how the tops of each peak are catching a ribbon of light. Tree adds interesting texture but needs more focus and I think should be farther left in the frame.', '2018-06-13 10:23:53.000000', NULL, 1),
(7571492, 1215565, 806, '<td valign="top">Nice abstract... sand? water? must be water from a height? Anyway the point is it keeps me guessing. leading lines make your eye travel throughout the image.</td>', 'Nice abstract... sand? water? must be water from a height? Anyway the point is it keeps me guessing. leading lines make your eye travel throughout the image.', '2018-06-13 10:25:41.000000', NULL, 1),
(7571493, 1215655, 806, '<td valign="top">lots of structures in the distance to tease the viewer. light rays are beautiful. wondering if more of the sidewalk in the foreground should be cropped out. nice light...dancing sparkles and balanced highlights.</td>', 'lots of structures in the distance to tease the viewer. light rays are beautiful. wondering if more of the sidewalk in the foreground should be cropped out. nice light...dancing sparkles and balanced highlights.', '2018-06-13 10:28:22.000000', NULL, 1),
(7571494, 1215385, 806, '<td valign="top">good clear shot. i don''t think the people add to the image. good perspective... atmospheric perspective?</td>', 'good clear shot. i don''t think the people add to the image. good perspective... atmospheric perspective?', '2018-06-13 10:29:51.000000', NULL, 1),
(7571495, 1215606, 806, '<td valign="top">my eye travels around and through this image. interesting shapes and i like the varied depths.</td>', 'my eye travels around and through this image. interesting shapes and i like the varied depths.', '2018-06-13 10:31:40.000000', NULL, 1),
(7571496, 1215633, 806, '<td valign="top">the clouds and hills/mountains both have great atmospheric perspective. the landscape on the whole is interesting with repeating shapes of the trees too. a little over sharpened. on the whole a good image.</td>', 'the clouds and hills/mountains both have great atmospheric perspective. the landscape on the whole is interesting with repeating shapes of the trees too. a little over sharpened. on the whole a good image.', '2018-06-13 10:34:11.000000', NULL, 1),
(7571498, 1215504, 806, '<td valign="top">beautiful night shot with leading lines of lights scattered in the hills. like the ferris wheel (?) peeking from behind the building on the left. lots going on in this city! the movement of the clouds shows time passing while everyone keeps on with their lives. excellent image and well done.</td>', 'beautiful night shot with leading lines of lights scattered in the hills. like the ferris wheel (?) peeking from behind the building on the left. lots going on in this city! the movement of the clouds shows time passing while everyone keeps on with their lives. excellent image and well done.', '2018-06-13 10:35:57.000000', NULL, 1),
(7571499, 1215613, 806, '<td valign="top">wonderful night shot! the little lights on the hills show life outside the city - even though you cannot see the hills well you infer they are there.</td>', 'wonderful night shot! the little lights on the hills show life outside the city - even though you cannot see the hills well you infer they are there.', '2018-06-13 10:37:28.000000', NULL, 1),
(7571500, 1215516, 806, '<td valign="top">beautiful distant image. clouds and further mountains along with the color of the sky bring the viewer into the image.</td>', 'beautiful distant image. clouds and further mountains along with the color of the sky bring the viewer into the image.', '2018-06-13 10:38:53.000000', NULL, 1),
(7571501, 1215635, 806, '<td valign="top">perspective and shape of the foreground frames this image beautifully. clear shot showing the objects and light hitting the water even in the far distance. I think the tree on the left can be cropped out as it doesn''t add to the story. nice tones throughout.</td>', 'perspective and shape of the foreground frames this image beautifully. clear shot showing the objects and light hitting the water even in the far distance. I think the tree on the left can be cropped out as it doesn''t add to the story. nice tones throughout.', '2018-06-13 10:41:29.000000', NULL, 1),
(7571503, 1215623, 806, '<td valign="top">simple. pleasant. could use more focus on the sailboat. overall lovely and tranquil.</td>', 'simple. pleasant. could use more focus on the sailboat. overall lovely and tranquil.', '2018-06-13 10:42:13.000000', NULL, 1),
(7571525, 1215504, 240421, '<td valign="top">Good shot !</td>', 'Good shot !', '2018-06-13 12:27:31.000000', NULL, 1),
(7571534, 1215298, 806, '<td valign="top">beautiful mountain scene with the angles of the hills leading the eye into the distance. quaint and quintessential church on the hilltop sets the scene of tranquility. beautiful light. repeating geometry in the hills. nice work!</td>', 'beautiful mountain scene with the angles of the hills leading the eye into the distance. quaint and quintessential church on the hilltop sets the scene of tranquility. beautiful light. repeating geometry in the hills. nice work!', '2018-06-13 13:02:37.000000', NULL, 1),
(7571535, 1215452, 806, '<td valign="top">interesting mood. eye is led by the lights into the image. clouds add depth.</td>', 'interesting mood. eye is led by the lights into the image. clouds add depth.', '2018-06-13 13:04:04.000000', NULL, 1),
(7571536, 1215649, 806, '<td valign="top">impending storms are always interesting. not sure if the cyan sky is too saturated or.....?</td>', 'impending storms are always interesting. not sure if the cyan sky is too saturated or.....?', '2018-06-13 13:05:31.000000', NULL, 1),
(7571537, 1215625, 806, '<td valign="top">very pretty scene of repeating shapes in the mountains. interesting nestled clouds between each. a little too sharpened?</td>', 'very pretty scene of repeating shapes in the mountains. interesting nestled clouds between each. a little too sharpened?', '2018-06-13 13:07:10.000000', NULL, 1),
